using System.Text;

namespace Acme.Generator;

/// <summary>Collects generated files, then writes them (or, with <c>--check</c>, reports which would change).</summary>
public sealed class GeneratedFiles(string repoRoot)
{
    public const string Notice = "<auto-generated> Edit platform.yaml instead and run scripts/generate.";

    private readonly SortedDictionary<string, string> _files = new(StringComparer.Ordinal);

    public string RepoRoot { get; } = repoRoot;

    public IReadOnlyDictionary<string, string> Files => _files;

    /// <summary>Adds a file whose comment syntax is <paramref name="comment"/> (for example <c>//</c> or <c>#</c>).</summary>
    public void Add(string relativePath, string comment, string body) =>
        AddRaw(relativePath, $"{comment} {Notice}\n{body}");

    public void AddXml(string relativePath, string body) =>
        AddRaw(relativePath, $"<!-- {Notice} -->\n{body}");

    /// <summary>Adds a file exactly as given (for formats without comments, or region-replaced files).</summary>
    public void AddRaw(string relativePath, string content)
    {
        var normalised = content.Replace("\r\n", "\n", StringComparison.Ordinal).TrimEnd('\n') + "\n";
        if (!_files.TryAdd(relativePath.Replace('\\', '/'), normalised))
            throw new InvalidOperationException($"{relativePath} is generated twice.");
    }

    /// <summary>Replaces the text between <c>BEGIN GENERATED: name</c> and <c>END GENERATED: name</c> markers in a hand-written file.</summary>
    public void ReplaceRegion(string relativePath, string name, string body)
    {
        var path = Path.Combine(RepoRoot, relativePath);
        var text = File.Exists(path) ? File.ReadAllText(path) : "";
        var begin = $"<!-- BEGIN GENERATED: {name} ({Notice}) -->";
        var end = $"<!-- END GENERATED: {name} -->";
        var start = text.IndexOf(begin, StringComparison.Ordinal);
        var stop = text.IndexOf(end, StringComparison.Ordinal);
        if (start < 0 || stop < start)
            throw new InvalidOperationException($"{relativePath} is missing the markers:\n{begin}\n{end}");
        AddRaw(relativePath, text[..(start + begin.Length)] + "\n" + body.TrimEnd('\n') + "\n" + text[stop..]);
    }

    /// <summary>Writes every file whose content changed. Returns the relative paths that changed.</summary>
    public IReadOnlyList<string> Write(bool checkOnly)
    {
        var changed = new List<string>();
        foreach (var (relative, content) in _files)
        {
            var path = Path.Combine(RepoRoot, relative);
            var current = File.Exists(path) ? File.ReadAllText(path) : null;
            if (current == content)
                continue;
            changed.Add(relative);
            if (checkOnly)
                continue;
            Directory.CreateDirectory(Path.GetDirectoryName(path)!);
            File.WriteAllText(path, content, new UTF8Encoding(encoderShouldEmitUTF8Identifier: false));
        }
        return changed;
    }
}
